Bash {"command":"cd "D:/code/tutors/test-course-python" && node -e "
const topics = require('./topics-8-10.js');
const baseFields = ['route','type','title','summary','contentMd','frontMatter','id','img','imgFile','video','videoids','hide','authLevel'];
let errors = [];

function check(obj, path) {
  baseFields.forEach(f => {
    if (!(f in obj)) errors.push(path + ' missing: ' + f);
  });
  if (obj.type === 'topic' || obj.type === 'unit') {
    if (!('los' in obj)) errors.push(path + ' missing: los');
  }
  if (obj.type === 'talk') {
    ['pdf','pdfFile'].forEach(f => { if (!(f in obj)) errors.push(path + ' missing: ' + f); });
    if (!obj.frontMatter || obj.frontMatter.marp !== 'true') errors.push(path + ' missing marp frontMatter');
  }
  if (obj.type === 'notebook') {
    if (!('cells' in obj)) errors.push(path + ' missing: cells');
    if (!('kernelLanguage' in obj)) errors.push(path + ' missing: kernelLanguage');
  }
  if (obj.type === 'lab') {
    ['los','pdf','pdfFile'].forEach(f => { if (!(f in obj)) errors.push(path + ' missing: ' + f); });
  }
  if (obj.los) obj.los.forEach((child, i) => check(child, path + '/los[' + i + '](' + (child.type || '?') + ')'));
}

topics.forEach((t, i) => check(t, 'topic[' + i + ']'));
if (errors.length) { console.log('ERRORS:'); errors.forEach(e => console.log('  ' + e)); }
else console.log('All objects pass structural validation!');
"","description":"Validate all learning objects have required fields"}

Bash {"command":"cd "D:/code/tutors/test-course-python" && node -e "
const topics = require('./topics-8-10.js');
const stepFields = ['title','shortTitle','contentMd','contentHtml','route','id','type'];
let errors = [];

const lab = topics[2].los[0].los[3]; // topic-10, unit-1, lab-oop
lab.los.forEach((step, i) => {
  stepFields.forEach(f => {
    if (!(f in step)) errors.push('step[' + i + '] missing: ' + f);
  });
  if (step.type !== 'step') errors.push('step[' + i + '] type should be step, got: ' + step.type);
});

if (errors.length) { console.log('ERRORS:'); errors.forEach(e => console.log('  ' + e)); }
else console.log('All 5 lab steps pass LabStep validation!');

// Also verify notebook cell structure
const cellFields = ['cellType','source','outputs','executionCount','metadata','id'];
let cellErrors = [];
topics.forEach((t,ti) => {
  t.los[0].los.forEach((lo,li) => {
    if (lo.cells) {
      lo.cells.forEach((c,ci) => {
        cellFields.forEach(f => {
          if (!(f in c)) cellErrors.push('t' + ti + '/lo' + li + '/cell' + ci + ' missing: ' + f);
        });
      });
    }
  });
});
if (cellErrors.length) { console.log('CELL ERRORS:'); cellErrors.forEach(e => console.log('  ' + e)); }
else console.log('All notebook cells pass cell validation!');

// Count Marp slides (by counting --- separators)
topics.forEach(t => {
  t.los[0].los.forEach(lo => {
    if (lo.type === 'talk') {
      const slides = lo.contentMd.split(/^---$/m).length;
      console.log('Talk ' + lo.id + ': ' + slides + ' slides');
    }
  });
});
